args.script:
(async () => {
  const r = await fetch('https://api.juejin.cn/user_api/v1/user/get', {credentials:'include'});
  const t = await r.text();
  let name = null, err = null;
  try {
    const j = JSON.parse(t);
    err = j.err_no;
    name = j.data && j.data.user_name || null;
  } catch (e) {}
  const href = location.href.split('?')[0];
  if (err !== 0 || !name) {
    return JSON.stringify({ok:false, href, err, name, head: t.slice(0, 120)});
  }
  return JSON.stringify({ok:true, href, name});
})()

(async () => {
  const ARGS = {{args_json}};
  try {
    if (!ARGS || !ARGS.title || String(ARGS.title).indexOf('CHANGE_ME') === 0) {
      return JSON.stringify({ok:false, err:'refusing sample title'});
    }
    if (!ARGS.mark_content) return JSON.stringify({ok:false, err:'mark_content required'});
    const body = {
      category_id: String(ARGS.category_id || '6809637773935378440'),
      tag_ids: ARGS.tag_ids || ['6809640625856577549', '6809640642101116936'],
      link_url: '',
      cover_image: '',
      is_gfw: 0,
      title: ARGS.title,
      brief_content: ARGS.brief_content || ARGS.title,
      is_english: 0,
      is_original: 1,
      edit_type: 10,
      html_content: '',
      mark_content: ARGS.mark_content,
      theme_ids: [],
      pics: []
    };
    const r = await fetch('/content_api/v1/article_draft/create', {
      method: 'POST', credentials: 'include',
      headers: {'content-type': 'application/json'},
      body: JSON.stringify(body)
    });
    const t = await r.text();
    let j = null; try { j = JSON.parse(t); } catch (e) {}
    const draft = j && j.data && (j.data.draft_id || j.data.id);
    if (!j || j.err_no !== 0 || !draft) {
      return JSON.stringify({ok:false, step:'create', status:r.status, err:j && j.err_no, msg:j && j.err_msg, head:t.slice(0, 160)});
    }
    const p = await fetch('/content_api/v1/article/publish', {
      method: 'POST', credentials: 'include',
      headers: {'content-type': 'application/json'},
      body: JSON.stringify({draft_id: String(draft)})
    });
    const pt = await p.text();
    let pj = null; try { pj = JSON.parse(pt); } catch (e) {}
    const aid = pj && pj.data && (pj.data.article_id || pj.data.id);
    return JSON.stringify({
      ok: !!(pj && pj.err_no === 0 && aid),
      draft_id: String(draft),
      article_id: aid ? String(aid) : null,
      url: aid ? ('https://juejin.cn/post/' + aid) : null,
      err: pj && pj.err_no,
      msg: pj && pj.err_msg,
      head: aid ? null : pt.slice(0, 180)
    });
  } catch (e) {
    return JSON.stringify({ok:false, err: e.name + ': ' + e.message});
  }
})()
